S=<out>/plugin-everwrite/skills/everwrite
cd <out>/h15-everwrite-inv-3
mkdir -p scripts && cp $S/scripts/tells.py scripts/tells.py
cat > scripts/lint-prose.js <<'EOF'
// Runs the everwrite checker (scripts/tells.py) on the README and the docs.
// The checker's rules are English, so folders of other languages are skipped.
const { readdirSync, statSync } = require('fs');
const { join } = require('path');
const { spawnSync } = require('child_process');

const SKIP = new Set(['docs/de', 'docs/fr']);

function collect(dir, out) {
  for (const name of readdirSync(dir).sort()) {
    const p = join(dir, name);
    if (SKIP.has(p)) continue;
    if (statSync(p).isDirectory()) collect(p, out);
    else if (p.endsWith('.md')) out.push(p);
  }
  return out;
}

const files = ['README.md', 'CHANGELOG.md', ...collect('docs', [])];
for (const py of ['python3', 'python']) {
  const r = spawnSync(py, [join(__dirname, 'tells.py'), ...files], { stdio: 'inherit' });
  if (!r.error) process.exit(r.status === null ? 1 : r.status);
}
console.error('lint:prose needs Python 3.9 or later');
process.exit(1);
EOF
python3 - <<'EOF'
import json
p=json.load(open('package.json'))
p['scripts']['lint:prose']='node scripts/lint-prose.js'
json.dump(p,open('package.json','w'),indent=2); open('package.json','a').write('\n')
c=open('.github/workflows/ci.yml').read()
c+="""  prose:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 22
      - run: npm run lint:prose
"""
open('.github/workflows/ci.yml','w').write(c)
r=open('README.md').read()
r=r.replace('> "Let me know','<!-- tells: off -->\n> "Let me know').replace('Delete it.\n','Delete it.\n<!-- tells: on -->\n')
open('README.md','w').write(r)
EOF
cat > CHANGELOG.md <<'EOF'
# Changelog

## 1.3.0

<!-- tells: off -->
- Rewrote the install page. The commit was titled "Clean up setup — again".
<!-- tells: on -->
- Fixed the broken link in the French notes.

## 1.2.0

- Added the German guide.

Versions 1.0 to 1.2 were internal drafts and never published. The security fixes from 1.1 to 1.2 are folded into 1.3.0.
EOF
cat > docs/guide.md <<'EOF'
# Acme guide

Acme is a shared workspace for your team's work and repositories.

## Getting started

Create a workspace, invite your team, and connect your first repository. The setup takes about 5 minutes.
EOF
npm run lint:prose; echo rc=$?
printf '# Bad\n\nThis robust tool delves into it — a testament to teamwork. Let me know if you need more!\n' > docs/new.md
npm run lint:prose >/dev/null; echo bad rc=$?; rm docs/new.md
npm test | tail -1; cat .github/workflows/ci.yml | tail -12

